type templateHTMLAlias = template.HTML
type recorderAlias = httptest.ResponseRecorder

func newRecorder() *recorderAlias            { return httptest.NewRecorder() }
func ui2JSONUnmarshal(b []byte, v any) error { return json.Unmarshal(b, v) }
func ui2JSONMarshal(v any) ([]byte, error)   { return json.Marshal(v) }

type ioReadCloser struct{ *strings.Reader }

func (ioReadCloser) Close() error { return nil }

var _ = io.EOF
var _ = http.MethodGet

	WorstSeverity string `json:"worst_severity,omitempty"`
	// InScope is whether the tools are allowed to touch this node. Burp dims out-of-scope branches
	// because the site map records everything the proxy saw, including third-party hosts the operator
	// has no authorisation for — and a map that shows an unauthorised host identically to an
	// authorised one invites someone to right-click it and attack it.
	//
	// A path node asks Scope.Contains, the same question the per-request gate asks. A host node is in
	// scope when its own root is, *or* when anything beneath it is — the truthful question for a
	// branch is "does this contain something you may touch", and answering it any other way misreads
	// two real rule shapes in opposite directions. An `include(h)` plus a path-scoped
	// `exclude(h, "/admin")` must leave the host lit, and an `include(h).with_path_prefix("/v1/")`
	// must also leave it lit even though `h`'s root is not itself in scope.
	//
	// Deliberately not MayContainHost: that is a pre-filter for attacks and answers a coarser question
	// than the sitemap asks. It refuses a host no include rule names, agreeing with Contains on the
	// "unlisted third party" case — but a path-scoped include (`include(h, "/v1/")`) still lights the
	// whole host to it, because "may an attack invent a path here" has to stay open for the host whose
	// /v1/ paths are authorised. The sitemap instead asks Contains per node, so it has the precision to
	// light /v1/ and dim the host root. This value only decides what is greyed; authorisation stays on
	// the bytes going out.
	InScope bool `json:"in_scope"`
	// HostName is the authority's host, carried on every node so the merge can group by it without
	// parsing Key. Never serialised: Key already states the identity to a client, and a second
	// spelling of the same fact on the wire is a second thing to keep right.
	HostName string `json:"-"`
	// Inserted marks a node the operator added themselves rather than one traffic was observed on
	// (amu). The two are kept apart for the reason the decision recorded: a node on the map means
	// either "we saw this" or "you wrote this down", and an operator reading the map needs to know
	// which — the counts beside an inserted node are all zero precisely because nothing was
	// requested, and saying so on the node is better than a node that looks observed and empty.
	//
	// Never omitempty: absent and false are the same JSON, and a client that read an absent
	// `inserted` as "this is a stored fact" would label every observed node as added.
	Inserted bool `json:"inserted"`
	// Unrequested marks a URL the live passive crawl saw linked from proxied traffic that nobody has
	// requested (t3zk), Burp's grey item. LinkedFrom is the page that linked to it.
	Unrequested  bool              `json:"unrequested,omitempty"`
	LinkedFrom   string            `json:"linked_from,omitempty"`
	AddedAt      *int64            `json:"added_at,omitempty"`
	LastExchange *int64            `json:"last_exchange"`
	Recent       []core.ExchangeID `json:"recent_exchanges"`
	Children     []sitemapNodeView `json:"children,omitempty"`
}

// sitemapTreeResp mirrors sitemap.ts's TreeResp.
// sitemapInsertReq is the request body sitemapInsert decodes (hoisted for its published schema, burpsy-react-ui-3zw0).
type sitemapInsertReq struct {
	Host string `json:"host"`
	Port uint16 `json:"port"`
	TLS  bool   `json:"tls"`
	Path string `json:"path"`
}

// sitemapInsert records one operator-added site-map node (amu).
//
// The response says which of the two things happened, because they are different facts an operator
// needs to know: a node they added, or a node that was ALREADY on the map because traffic to it was
// observed. Reporting the second as a success would tell an operator their URL was recorded when it
// was on the map for a stronger reason, and the distinction is the whole point of keeping inserts
// separate from observations.
func (s *Server) sitemapInsert(w http.ResponseWriter, r *http.Request) {
	var req sitemapInsertReq
	if err := requestJSON(w, r, io.LimitReader(r.Body, 1<<16)).Decode(&req); err != nil {
		http.Error(w, "body must be JSON {\"host\": \"h\", \"port\": n, \"tls\": bool, \"path\": \"/p\"}",
			http.StatusBadRequest)
		return
	}
	req.Host = strings.TrimSpace(req.Host)
	if req.Host == "" {
		http.Error(w, "a host is required: the map is a tree of authorities, and a node with no host "+
			"is not one", http.StatusBadRequest)
		return
	}
	if req.Port == 0 {
		http.Error(w, "a port is required: a map node names one authority, and app.test:0 is not one. "+
			"The row menu takes the port from the exchange it was invoked on", http.StatusBadRequest)
		return
	}
	req.Path = strings.TrimSpace(req.Path)
	if req.Path != "" && !strings.HasPrefix(req.Path, "/") {
		req.Path = "/" + req.Path
	}
	already := s.sitemap.Insert(req.Host, req.Port, req.TLS, req.Path, time.Now())
	body := map[string]any{
		"inserted":     req.Host + req.Path,
		"already_seen": already,
	}
	if already {
		body["note"] = "that host and path are already on the map because traffic to them, or beneath them, was observed, " +
			"which is a stronger fact than a note to self"
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(body)
}

// sitemapDeleteReq is the request body sitemapDelete decodes (hoisted for its published schema, burpsy-react-ui-3zw0).
type sitemapDeleteReq struct {
	Host string `json:"host"`
	Port uint16 `json:"port"`
	TLS  bool   `json:"tls"`
	Path string `json:"path"`
	Kind string `json:"kind"`
}

// sitemapDelete validates the node fields the UI sent and suppresses that host, branch or item.
// A wrong-verb answer is the mux's business; a body naming no host, or a path with no kind, is a
// 400 saying what was wrong — not a silent success that removed nothing.
func (s *Server) sitemapDelete(w http.ResponseWriter, r *http.Request) {
	var req sitemapDeleteReq
	if err := requestJSON(w, r, io.LimitReader(r.Body, 1<<16)).Decode(&req); err != nil || req.Host == "" {
		http.Error(w, "body must be JSON {\"host\": \"h\", \"port\": n, \"tls\": bool, \"path\": \"\", \"kind\": \"host\"} (path \"\" = whole host) or {.., \"path\": \"/p\", \"kind\": \"item\"|\"branch\"}", http.StatusBadRequest)
		return
	}
	// The literals match sitemap's suppressItem/suppressBranch values; they are spelled here rather
	// than exported from sitemap because the wire vocabulary is this API's contract, not the map
	// package's.
	if req.Path != "" && req.Kind != "item" && req.Kind != "branch" {
		http.Error(w, "kind must be \"item\" or \"branch\" when a path is given", http.StatusBadRequest)
		return
	}
	if req.Path == "" {
		req.Kind = "host"
	}
	s.sitemap.Suppress(sitemap.HostKey(req.Host, req.Port, req.TLS), req.Path, req.Kind)
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]any{"suppressed": req.Host + req.Path, "kind": req.Kind})
}

func (s *Server) sitemapGet(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	hostFilter := q.Get("host")
	pathFilter := q.Get("path")

	// No Sync here. The map follows the store (see the sitemap package docs on CRAWL-05), so it is
	// already current; rebuilding it on every read would also make a broken subscription invisible,
	// because the read path would quietly do the subscription's job.
	exchanges := s.store.Exchanges()
	// Built once for the whole tree rather than per node: findings are indexed by node key, and
	// re-walking every finding at every node would be quadratic in a map that only needs building
	// once.
	issues := s.issuesByNode()
	var nodeCount int

	// One snapshot serves both the observed tree and the dedupe of inserted and unrequested items
	// below, so the two agree with each other and the map is cloned once per request.
	hosts := s.sitemap.Hosts()
	// Allocated, never nil: an empty map is "tree":[] on the wire, not null (burpsy-react-ui-9n01).
	// The UI types the field as an array, and a null there breaks any client that iterates it where
	// it should have rendered an empty site map.
	tree := make([]sitemapNodeView, 0, len(hosts))
	for _, host := range hosts {
		if hostFilter != "" && host.Host != hostFilter {
			continue
		}
		children := s.foldPaths(host, pathFilter, &nodeCount, issues)
		// The host row is a node the tree draws, so it is in the count the UI prints beside the rows
		// it renders ("N of M nodes"), as a host row synthesised for an insert already was.
		nodeCount++
		lastEx := lastExchangeID(exchanges, host.Host)
		hostIssues, hostWorst := 0, -1
		hostMimes := map[string]struct{}{}
		for _, c := range children {
			hostIssues += c.SubtreeIssues
			if r := severityRankOf(c.WorstSeverity); r > hostWorst {
				hostWorst = r
			}
			for _, m := range c.Mimes {
				hostMimes[m] = struct{}{}
			}
		}
		tree = append(tree, sitemapNodeView{
			Key:           nodeKey(host.Host, host.Port, host.TLS, ""),
			Segment:       host.Host,
			Path:          host.Host,
			Port:          host.Port,
			TLS:           host.TLS,
			Depth:         0,
			Exchanges:     len(host.Paths),
			Requested:     true,
			SubtreeCount:  len(host.Paths),
			ChildCount:    len(children),
			Methods:       []string{},
			Statuses:      []int{},
			Mimes:         sortedSetKeys(hostMimes),
			Params:        []string{},
			LastExchange:  lastEx,
			Recent:        []core.ExchangeID{},
			SubtreeIssues: hostIssues,
			WorstSeverity: severityName(hostWorst),
			InScope:       s.scope.Contains(host.Host, host.Port, "/", host.TLS) || anyInScope(children),
			Children:      children,
		})
	}

	// Operator-added nodes (amu), merged in after the observed tree so the fold above never has to
	// know about them. An insert naming a path that was already observed is not emitted: the
	// observation is the stronger fact, and the caller was told exactly that at insert time.
	//
	// Both kinds are placed by node identity (sitemap.NodePath), the rule the fold uses, never by the
	// raw path (burpsy-react-ui-vc98): a grey /r?next=/a/b split on the slashes in its query and drew
	// stray /r?next= and /r?next=/a folders, and two links to /search with different queries drew two
	// grey rows for one node. Items that share a node become one row carrying the union of their
	// query parameter names, exactly as the fold folds query variants of an observed path. An
	// operator's insert outranks a grey item at the same node: "you wrote this down" is the stronger
	// of the two unobserved facts.
	insertedPaths := make([]sitemapNodeView, 0)
	extraParams := make([]map[string]struct{}, 0)
	extraAt := map[string]int{}
	// Built on first use, once per request: a lookup per merged item instead of a site-map clone and
	// a scan of every observed path per merged item, which made this read O(merged x observed).
	var observed observedIndex
	isObserved := func(in *sitemap.InsertedNode) bool {
		if observed == nil {
			observed = newObservedIndex(hosts)
		}
		return observed.has(in)
	}
	// addExtra folds one item into the row for its node, or starts that row.
	addExtra := func(v sitemapNodeView, raw string) {
		_, rawQuery := splitPathQuery(raw)
		if i, ok := extraAt[v.Key]; ok {
			for _, name := range queryParamNames(rawQuery) {
				extraParams[i][name] = struct{}{}
			}
			cur := &insertedPaths[i]
			// The earliest sighting dates the row, and its source page is the one shown, so the row
			// does not change its story every time another query variant is linked.
			if cur.Unrequested && v.Unrequested && v.AddedAt != nil && cur.AddedAt != nil && *v.AddedAt < *cur.AddedAt {
				cur.AddedAt, cur.LinkedFrom = v.AddedAt, v.LinkedFrom
			}
			if cur.Inserted && v.Inserted && v.AddedAt != nil && cur.AddedAt != nil && *v.AddedAt < *cur.AddedAt {
				cur.AddedAt = v.AddedAt
			}
			return
		}
		params := map[string]struct{}{}
		for _, name := range queryParamNames(rawQuery) {
			params[name] = struct{}{}
		}
		extraAt[v.Key] = len(insertedPaths)
		insertedPaths = append(insertedPaths, v)
		extraParams = append(extraParams, params)
	}
	for _, in := range s.sitemap.Inserts() {
		if hostFilter != "" && in.Host != hostFilter {
			continue
		}
		if pathFilter != "" && !strings.Contains(in.Path, pathFilter) {
			continue
		}
		if in.Path != "" && isObserved(in) {
			continue
		}
		// A host-only insert has no path: it is the host row itself, not a child of it.
		node, depth := "", 0
		if in.Path != "" {
			node, depth = sitemap.NodePath(in.Path), sitemap.NodeDepth(in.Path)
		}
		added := in.Added.UnixMilli()
		addExtra(sitemapNodeView{
			Key:      nodeKey(in.Host, in.Port, in.TLS, node),
			HostName: in.Host,
			Segment:  pathSegment(node),
			Path:     node,
			Port:     in.Port,
			TLS:      in.TLS,
			Depth:    depth,
			Inserted: true,
			AddedAt:  &added,
			Methods:  []string{},
			Statuses: []int{},
			Mimes:    []string{},
			Params:   []string{},
			Recent:   []core.ExchangeID{},
			Children: []sitemapNodeView{},
			InScope:  s.scope.Contains(in.Host, in.Port, pathOrRoot(node), in.TLS),
		}, in.Path)
	}
	// Unrequested items (t3zk), merged the same way and dropped once anything has requested them.
	for _, un := range s.sitemap.Unrequested() {
		if hostFilter != "" && un.Host != hostFilter {
			continue
		}
		if pathFilter != "" && !strings.Contains(un.Path, pathFilter) {
			continue
		}
		as := &sitemap.InsertedNode{Host: un.Host, Port: un.Port, TLS: un.TLS, Path: un.Path}
		if isObserved(as) {
			continue
		}
		node := sitemap.NodePath(un.Path)
		key := nodeKey(un.Host, un.Port, un.TLS, node)
		if i, ok := extraAt[key]; ok && insertedPaths[i].Inserted {
			continue
		}
		seen := un.Seen.UnixMilli()
		addExtra(sitemapNodeView{
			Key:         key,
			HostName:    un.Host,
			Segment:     pathSegment(node),
			Path:        node,
			Port:        un.Port,
			TLS:         un.TLS,
			Depth:       sitemap.NodeDepth(un.Path),
			Unrequested: true,
			LinkedFrom:  un.From,
			AddedAt:     &seen,
			Methods:     []string{},
			Statuses:    []int{},
			Mimes:       []string{},
			Params:      []string{},
			Recent:      []core.ExchangeID{},
			Children:    []sitemapNodeView{},
			InScope:     s.scope.Contains(un.Host, un.Port, node, un.TLS),
		}, un.Path)
	}
	for i := range insertedPaths {
		insertedPaths[i].Params = sortedSetKeys(extraParams[i])
	}
	inScope := func(host string, port uint16, tls bool, path string) bool {
		return s.scope.Contains(host, port, path, tls)
	}
	tree, nodeCount = mergeInsertedIntoTree(tree, insertedPaths, nodeCount, inScope)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(sitemapTreeResp{
		Exchanges: len(exchanges),
		Nodes:     nodeCount,
		Synced:    len(exchanges),
		InFlight:  0,
		Tree:      tree,
	})
}

// observedIndex answers whether the observed tree already holds a path under its host, for the
// inserted and unrequested items merged into GET /api/sitemap. A path is observed when its node
// (sitemap.NodePath: query removed, normalised) is the node of any stored path key, or when it names
// a folder that anything observed sits beneath: the fold synthesises ancestor folders, so an insert
// naming /api/ would otherwise produce a second /api/ node beside the synthesised one. "/" is
// observed under any host that has a path at all.
//
// Node against node, never node against raw key (burpsy-react-ui-u6f8): the stored keys keep the
// query ("/search?q=1") and comparing the item's stripped path to them left a linked /search?q=1
// grey after /search?q=1 was requested. A request for /search?q=1 also clears a linked
// /search?q=2: the fold draws both as the one requested /search node with q in its parameter list,
// so a grey /search?q=2 beside it would be a second row for a node the map already shows as
// requested — the per-query sibling leaf the fold was written to remove.
type observedIndex map[observedHostKey]*observedHost

type observedHostKey struct {
	host string
	port uint16
	tls  bool
}

type observedHost struct {
	// keys are the nodes of the stored path keys: sitemap.NodePath of each, so "/search?q=1" is held
	// as "/search".
	keys map[string]struct{}
	// folders holds every clean observed path's prefixes that end in "/" ("/", "/a/", "/a/b/" for
	// /a/b/c), which is the set a folder query X matches as HasPrefix(path, X+"/").
	folders map[string]struct{}
	any     bool
}

func newObservedIndex(hosts []*sitemap.HostNode) observedIndex {
	idx := observedIndex{}
	for _, h := range hosts {
		k := observedHostKey{h.Host, h.Port, h.TLS}
		oh := idx[k]
		if oh == nil {
			oh = &observedHost{keys: map[string]struct{}{}, folders: map[string]struct{}{}}
			idx[k] = oh
		}
		for key := range h.Paths {
			cleanPath := sitemap.NodePath(key)
			oh.keys[cleanPath] = struct{}{}
			oh.any = true
			for i := 0; i < len(cleanPath); i++ {
				if cleanPath[i] == '/' {
					oh.folders[cleanPath[:i+1]] = struct{}{}
				}
			}
		}
	}
	return idx
}

func (idx observedIndex) has(in *sitemap.InsertedNode) bool {
	oh := idx[observedHostKey{in.Host, in.Port, in.TLS}]
	if oh == nil {
		return false
	}
	clean := sitemap.NodePath(in.Path)
	if _, ok := oh.keys[clean]; ok {
		return true
	}
	if !oh.any {
		return false
	}
	if clean == "/" {
		return true
	}
	_, ok := oh.folders[strings.TrimSuffix(clean, "/")+"/"]
	return ok
}

// pathOrRoot is the path scope questions are asked about: an inserted host node has no path, and
// Contains wants a real one.
func pathOrRoot(p string) string {
	if p == "" {
		return "/"
	}
	return p
}

// mergeInsertedIntoTree grafts operator-added and unrequested nodes onto the observed tree.
//
// The shape the map already has is host → path folders → leaves, and an insert can land anywhere in
// it: under a host that was observed, under a host that was not, or at a folder level between two
// observed nodes. Synthesising the missing ancestors is what keeps the tree a tree — an insert under
// an unseen host needs a host row to sit under, and an insert of /api/v1/users needs /api and

