	// the drift snapshot for whole-document writes. Same single-use LoadAndDelete semantics as
	// ui2TriageReviews, bounded by ui2SettingsWriteReviewCap, expiring with ConfirmTTL.
	ui2SettingsWriteReviews sync.Map
