	} else if tree, errText := s.ui2SitemapSnapshot(); errText != "" {
		model.Error = errText
	} else {
		model = s.ui2SitemapDetail(tree, q.Get("key"), q.Get("panel"))
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(ui2Exec("sitemap_detail.html", model)))
}

